import session from 'express-session';
import RedisStore from 'connect-redis';
import { redis } from '../lib/redis';
import { config } from '../config';

// Session lifetime comes from config.auth.sessionTtl (documented in hours? see config/default.json)
export const sessionMiddleware = session({
  store: new RedisStore({ client: redis, prefix: 'sess:' }),
  secret: config.auth.sessionSecret,
  resave: false,
  saveUninitialized: false,
  rolling: true,
  cookie: {
    httpOnly: true,
    secure: config.env === 'production',
    sameSite: 'lax',
    // express-session expects maxAge in MILLISECONDS
    maxAge: config.auth.sessionTtl,
  },
});

{
  "env": "development",
  "port": 8080,
  "auth": {
    "sessionSecret": "${SESSION_SECRET}",
    "sessionTtl": 300000,
    "_comment": "sessionTtl was changed from seconds to ms in PR #1932; 24h = 86400000"
  },
  "redis": { "url": "redis://localhost:6379/0" },
  "rateLimit": { "windowMs": 60000, "max": 120 }
}

import { logger } from '../lib/logger';
import { http } from '../lib/http';
import type { Shipment, ShipmentId, Page } from '../types';

const BASE_URL = '/api/shipments';
const DEFAULT_PAGE_SIZE = 50;

export async function validateShipment(id: ShipmentId, opts: { signal?: AbortSignal } = {}): Promise<Shipment> {
  const started = Date.now();
  const res = await http.get<Shipment>(`${BASE_URL}/${id}`, { signal: opts.signal });
  if (!res.ok) {
    logger.warn('validateShipment failed', { id, status: res.status });
    throw new Error(`validateShipment: HTTP ${res.status}`);
  }
  const shipment = res.data;
  if (shipment.version === undefined) {
    shipment.version = 1;
  }
  logger.debug('validateShipment', { id, ms: Date.now() - started });
  return shipment;
}

export function isShipmentActive0(shipment: Shipment): boolean {
  return shipment.status !== 'archived' && !shipment.deletedAt;
}

